import os, re
from pathlib import Path
from collections import Counter, defaultdict

root = Path("/Users/serro/Documents/dev/n/nucleus")
skip_dirs = {".git", "node_modules", ".svelte-kit", "dist", "build", ".turbo", "coverage", ".auth"}
exts = {".ts", ".tsx", ".js", ".jsx", ".mjs", ".cjs", ".svelte"}
pat = re.compile(r"""(?:from|import|require|vi\.mock|jest\.mock)\s*\(?\s*['"]([^'"]+)['"]""", re.M)

print("=== ALL client parent-relative imports ===")
client_hits = []
lib_hits = []
same_dir_client = Counter()
alias_client = Counter()

for dirpath, dirnames, filenames in os.walk(root / "client"):
    dirnames[:] = [d for d in dirnames if d not in skip_dirs and not d.startswith(".")]
    for fn in filenames:
        p = Path(dirpath) / fn
        if p.suffix not in exts:
            continue
        rel = p.relative_to(root).as_posix()
        text = p.read_text(encoding="utf-8", errors="ignore")
        specs = pat.findall(text)
        pkg = rel.split("/")[1] if "/" in rel else rel
        for spec in specs:
            if spec.startswith("../"):
                client_hits.append((rel, spec))
            elif spec == "$lib" or spec.startswith("$lib/"):
                lib_hits.append((rel, spec))
            elif spec.startswith("./"):
                same_dir_client[pkg] += 1
            elif spec.startswith("@nucleum/") or spec.startswith("@21n/"):
                alias_client[pkg] += 1

for rel, spec in sorted(client_hits):
    print(f"  {rel}")
    print(f"      {spec}")

print(f"\nclient parent-relative import count={len(client_hits)} files={len({f for f,_ in client_hits})}")
print("\n=== client same-dir ./ by package ===")
for k,v in same_dir_client.most_common():
    print(f"  {k:20} {v}")
print("\n=== client alias by package (top) ===")
for k,v in alias_client.most_common(15):
    print(f"  {k:20} {v}")

print(f"\n=== client $lib count={len(lib_hits)} files={len({f for f,_ in lib_hits})} ===")
lib_pkg = Counter(f.split("/")[1] for f,_ in lib_hits)
for k,v in lib_pkg.most_common():
    print(f"  {k:20} {v}")
print("sample $lib:")
for rel, spec in lib_hits[:15]:
    print(f"  {rel}: {spec}")

print("\n=== eslint coverage gap: svelte parent-relative in client ===")
for rel, spec in client_hits:
    if rel.endswith(".svelte"):
        print(f"  {rel}: {spec}")
